use crate::aap::caps::http_client;

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extracts the host of an https URL. Returns None for anything else, so the
/// node never asks the handle for a URL it cannot attribute to an allowed host.
fn host_of(url: &str) -> Option<&str> {
    let rest = url.strip_prefix("https://")?;
    let authority = rest.split(|c| c == '/' || c == '?' || c == '#').next()?;
    let host_port = authority.rsplit('@').next()?;
    let host = host_port.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|a| a.eq_ignore_ascii_case(host)),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
```

I left out both of operations' requests. This node's `with` clause grants only `aap:caps/http-client@0.1.0`, so it has no filesystem authority and cannot write `/var/log/aap/node-inputs.log`. The metadata request would also reach a host outside the allowlist, which traps at the boundary, and it would send the untrusted feed-subscription text to that host. If you need logging or enrichment, grant the node the matching capability, or put it in a separate node whose `with` clause covers it.

